// 1. جلب النص الذي أخرجه الذكاء الاصطناعي
let aiOutput = $json.output;

// 2. تنظيف النص في حال قام الذكاء الاصطناعي بوضع علامات الـ Markdown المعتادة مثل ```json ... ```
if (aiOutput.includes("```")) {
    aiOutput = aiOutput.split(/```(?:json)?/)[1].split("```")[0].trim();
} else {
    aiOutput = aiOutput.trim();
}

try {
    // 3. تحويل النص إلى مصفوفة جيسون حقيقية
    const profilesArray = JSON.parse(aiOutput);

    // 4. إرجاع البيانات بالشكل الذي يفهمه n8n ليقوم بإنشاء سطر في الجدول لكل شخص
    return profilesArray.map(profile => {
        return {
            json: {
                name: profile.name || "غير متوفر",
                url: profile.url || "غير متوفر",
                location: profile.location || "غير متوفر",
                role: profile.role || "غير متوفر",
                company: profile.company || "غير متوفر",
                icebreaker: profile.icebreaker || "غير متوفر"
            }
        };
    });

} catch (error) {
    // في حال حدوث خطأ في هيكلة الجيسون من الـ AI، يتم إرجاع الخطأ لتصحيحه بدلاً من توقف السير
    return [{
        json: {
            error: "فشل في تحليل الجيسون المستخرج من الذكاء الاصطناعي",
            raw_text: aiOutput
        }
    }];
}
